mapper.select:
SELECT  FROM wechat_message

    AND create_time >= #{since}
    AND name = #{chat}
    AND status = #{status}

ORDER BY sort_seq ASC LIMIT #{max}

SELECT  FROM wechat_message
WHERE classify_status IN ('PENDING','FAILED')
ORDER BY sort_seq ASC LIMIT #{max}

SELECT * FROM (
    SELECT  FROM wechat_message
    WHERE username = #{username}
    ORDER BY sort_seq DESC LIMIT #{max}
) recent ORDER BY sort_seq ASC

SELECT  FROM wechat_message
WHERE classify_status = 'SUCCESS'
  AND category_source IN ('LLM','CACHE')
  AND msg_category IN
  #{cat}
  AND create_time >= #{since}
  AND (entry_status IN ('PENDING','FAILED')
       OR (entry_status = 'PROCESSING' AND entry_at < DATE_SUB(NOW(), INTERVAL #{timeoutSec} SECOND)))
  AND create_time <= DATE_SUB(NOW(), INTERVAL #{minAgeSec} SECOND)
  AND name = #{chat}

      AND name IN #{nm}

ORDER BY sort_seq ASC LIMIT #{max}

SELECT  FROM wechat_message
WHERE classify_status = 'SUCCESS'
  AND category_source IN ('LLM','CACHE')
  AND msg_category IN ('INQ','OFFER')
  AND (
        (entry_status IN ('SUCCESS','SUCCESS_WARN') AND task_status IN ('PENDING','FAILED'))
        OR (entry_status = 'SKIPPED' AND task_status IN ('PENDING','FAILED')
            AND (entry_message LIKE '群未映射%' OR entry_message LIKE '群映射冲突%'))
        OR (task_status = 'PROCESSING' AND task_at < DATE_SUB(NOW(), INTERVAL #{timeoutSec} SECOND))
      )
  AND create_time >= #{since}
  AND name = #{chat}
ORDER BY sort_seq ASC LIMIT #{max}

SELECT  FROM wechat_message

    AND create_time >= #{beginTime}
    AND create_time <= #{endTime}
    AND name LIKE CONCAT('%', #{name}, '%')
    AND msg_category = #{msgCategory}
    AND classify_status = #{classifyStatus}
    AND entry_status = #{entryStatus}
    AND task_status = #{taskStatus}

        AND (content LIKE CONCAT('%', #{keyword}, '%')
          OR name LIKE CONCAT('%', #{keyword}, '%')
          OR sender LIKE CONCAT('%', #{keyword}, '%')
          OR entry_message LIKE CONCAT('%', #{keyword}, '%')
          OR task_message LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY create_time DESC, id DESC
